*{box-sizing:border-box}body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:900px;margin:30px auto;padding:0 16px}.panel{background:#fff;padding:22px;border:1px solid #e4ebe5;border-radius:14px;margin:16px 0}h1{font-size:26px}h2{font-size:18px;margin:0 0 8px}.muted{color:#718077;font-size:13px;line-height:1.6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}label{display:block;font-size:13px;font-weight:700;margin:14px 0}input,select{display:block;width:100%;padding:11px;border:1px solid #dfe6e0;border-radius:8px;margin-top:7px;font:inherit;background:#fff}button{background:#176b50;color:white;border:0;border-radius:8px;padding:13px 18px;font-weight:700;cursor:pointer}.note{background:#fff6e7;color:#76551c;padding:12px;border-radius:9px;font-size:13px;margin:12px 0}.notice{padding:12px;border-radius:9px;font-size:13px;margin:12px 0}.notice.success{background:#eaf5ed;color:#176b50}.notice.error{background:#fff0ed;color:#8b3325}.test-button{background:#315d85;margin:6px 0 10px}.status{font-size:12px;font-weight:750;color:#176b50}.clear{display:flex;gap:9px;align-items:center;font-weight:600}.clear input{width:auto;margin:0}@media(max-width:650px){.grid{grid-template-columns:1fr}.panel{padding:16px}}</style></head><body><main class="wrap"><h1>Platform ayarları</h1><form method="post" action="/admin/settings"><?= csrf_field() ?>
<section class="panel"><h2>Genel ayarlar</h2><div class="grid">
<label>Platform komisyonu (%)<input type="number" name="commission" min="0" max="50" step=".1" value="<?= e($settings['platform.commission_percent']??'12') ?>"></label>
<label>Varsayılan para birimi<input name="currency" maxlength="3" pattern="[A-Za-z]{3}" value="<?= e($settings['app.currency']??'TRY') ?>"></label>
<label>Zaman dilimi<input name="timezone" value="<?= e($settings['app.timezone']??'Europe/Istanbul') ?>"></label></div></section>
